function correctGuideProse(guide) {
  const id = `${guide.state_abbr}/${guide.city_slug}/${guide.guide_slug}`;
  const result = { ...guide };
  for (const correction of editorialCorrections) {
    if (correction.guide !== id) continue;
    const path = correction.field.split('.');
    if (path.length === 1) {
      if (result[path[0]] !== correction.before) throw new Error(`Market guide editorial review required: ${id} ${correction.field}`);
      result[path[0]] = correction.after;
    } else {
      const [field, index, property] = path;
      result[field] = [...result[field]];
      const value = property ? result[field][index][property] : result[field][index];
      if (value !== correction.before) throw new Error(`Market guide editorial review required: ${id} ${correction.field}`);
      result[field][index] = property
        ? { ...result[field][index], [property]: correction.after }
        : correction.after;
    }
  }
  return result;
}

// Verified 2026-10-26: report p1 pricing and p3 all-class total. This is
// a historical observation, never a current quote or a city-wide all-property rate.
const sanFranciscoOfficeRent = Object.freeze({
  city_slug: 'san-francisco', state_abbr: 'CA', space_type: 'office-space',
  value: '$69.16 per square foot per year', units: 'USD/SF/year, gross asking, all office classes',
  period: 'Q1 2026', start: '2026-01-01', end: '2026-03-31',
  name: 'Cushman & Wakefield San Francisco Office MarketBeat Q1 2026',
  url: 'https://assets.cushmanwakefield.com/-/media/cw/marketbeat-pdfs/2026/q1/us-reports/office/san-francisco_americas_marketbeat_office_q12026.pdf?rev=f4082512d6c0402782606fbf8876769c',
  reviewed: true,
});

// Only internally reviewed evidence may be supplied here. Shape validation alone
// is not source verification; incoming guide/source metadata never reaches this API.
function historicalRent(evidence, guide) {
  if (!evidence || evidence.reviewed !== true || guide.guide_kind !== 'space-type' ||
      ['city_slug', 'state_abbr', 'space_type'].some(key => evidence[key] !== guide[key]) ||
      !evidence.value || !evidence.units || !evidence.period || !evidence.name ||
      !/^https:\/\//.test(evidence.url || '') ||
      !/^\d{4}-\d{2}-\d{2}$/.test(evidence.start || '') ||
      !/^\d{4}-\d{2}-\d{2}$/.test(evidence.end || '') || evidence.start > evidence.end) return {};
  return {
    average_rent: evidence.value,
    rent_basis: `${evidence.name}: ${guide.city} overall office, all property classes; quarter-end ${evidence.period} gross/full-service asking rent, not achieved rent or an average over the quarter. Historical observation, not a current quote.`,
    market_date: `${evidence.period} (historical)`,
    temporal_coverage: `${evidence.start}/${evidence.end}`,
    verified_sources: [{ name: evidence.name, url: evidence.url }],
  };
}

function applyGuideEvidencePolicy(guide) {
  return {
    ...correctGuideProse(guide),
    market_date: '',
    temporal_coverage: '',
    verified_sources: [],
    // Source labels/year pairs do not establish population table, geography or period.
    population: '',
    population_label: '',
    employment_count: '',
    employment_count_label: '',
    establishment_count: '',
    establishment_count_label: '',
    unemployment_rate: '',
    average_rent: '',
    rent_basis: '',
    trends: [],
    market_snapshot: null,
    ...historicalRent(sanFranciscoOfficeRent, guide),
  };
}

module.exports = { applyGuideEvidencePolicy, historicalRent, editorialCorrections };
